-- ============================================================
-- DATA SEED: RealTime_Metrics
-- Purpose:
--   Populate the RealTime_Metrics table with high-frequency,
--   time-series sensor data representing real-world footfall,
--   dwell behavior, and traffic conditions across multiple
--   Cairo locations.
--
-- Key Attributes:
--   location_id        → FK reference to Location_Metadata
--   timestamp          → Sensor capture time (TIMESTAMPTZ)
--   people_count       → Detected pedestrian count
--   dwell_time_avg     → Average dwell time (minutes)
--   vehicle_count      → Detected vehicle count
--   congestion_level   → Qualitative traffic state
--                         (low, medium, high)
--   data_quality_flag  → Data integrity indicator
--                         0 = valid
--                         1 = anomalous / degraded
--
-- Intended Use:
--   - Real-time analytics & monitoring dashboards
--   - Feature generation for demand & revenue prediction
--   - Traffic and crowd behavior modeling
--   - Stress-testing ETL, data validation, and ML pipelines
--
-- Notes:
--   • Dataset is synthetic but behaviorally realistic.
--   • Designed for analytical robustness testing rather
--     than transactional accuracy.
--   • Scales horizontally with additional generated rows.
-- ============================================================

TRUNCATE TABLE RealTime_Metrics RESTART IDENTITY CASCADE;

